"""Standalone developer evidence for corrected units and conservative geometry.
Plots are scientific artifacts; archived0.9.3/0.9.4 evidence stays unchanged.
"""
import json,math,html,shutil
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path('test-results/convergence');out=Path('docs/speaker-design/models/convergence-upgrade');out.mkdir(parents=True,exist_ok=True)
current=json.loads(Path('test-results/anatomy/comparison.json').read_text());old=json.loads(Path('docs/speaker-design/models/anatomy-2006-comparison/comparison.json').read_text());check=json.loads((root/'comparison.json').read_text());source=json.loads(Path('examples/anatomy-2006-traces.json').read_text())
c=next(c for c in current['cases'] if c['id']=='stuffed');before=next(c for c in old['cases'] if c['id']=='stuffed')
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.2,'savefig.facecolor':'white'})
fig,axes=plt.subplots(1,2,figsize=(12,4.6),layout='constrained')
for case,style,label in [(before,':','Earlier implementation'),(c,'-','Corrected source units')]:
 r=case['openingToDriverRatio']['rows'];axes[0].semilogx([v['frequency'] for v in r],[v['actual'] for v in r],style,label=label)
 r=case['simulation'];axes[1].semilogx([v['frequency'] for v in r],[v['impedance'] for v in r],style,label=label)
r=c['openingToDriverRatio']['rows'];axes[0].scatter([v['frequency'] for v in r],[v['expected'] for v in r],s=12,facecolors='none',edgecolors='#222',label='Published graph readings')
r=next(t for t in source['traces'] if t['case']=='stuffed' and t['metric']=='impedance')['samples'];axes[1].scatter([v[0] for v in r],[v[1] for v in r],s=12,facecolors='none',edgecolors='#222',label='Published graph readings')
for ax in axes:ax.set_xlim(10,800);ax.set_xlabel('Frequency (Hz)');ax.legend(fontsize=8)
axes[0].set_ylabel('Opening − driver contribution (dB)');axes[0].set_title('Common drive/distance gain cancels')
axes[1].set_ylabel('Input impedance (Ω)');axes[1].set_ylim(0,55);axes[1].set_title('Stuffed line: independent second observable')
fig.suptitle('King2006 stuffed line — source unit correction, no coefficient fitting')
fig.savefig(out/'king-correction.png',dpi=160);plt.close(fig)
fig,axes=plt.subplots(1,2,figsize=(12,4.3),layout='constrained')
axes[0].plot([20,16,12],[68.8,74.760192,63.258624],'o:',label='Earlier whole-cell volume');axes[0].plot([20,16,12],[68.58]*3,'o-',label='Conservative cut cells');axes[0].axhline(68.58,color='#555',lw=.8,label='CAD body');axes[0].invert_xaxis();axes[0].set(xlabel='Grid pitch (mm)',ylabel='Cavity body (L)',title='Volume error corrected');axes[0].legend(fontsize=8)
xs=['20 → 16','16 → 12','Shifted 12','Larger exterior'];diff=check['refinements']+[check['shift'],check['padding']]
axes[1].plot(xs,[100*d['impedance'] for d in diff],'o-',label='Complex impedance');axes[1].plot(xs,[100*d['pressure'] for d in diff],'o-',label='Maximum fixed-probe pressure');axes[1].axhline(1,color='#2464b4',ls=':',lw=1,label='1% impedance limit');axes[1].axhline(2,color='#d26e22',ls=':',lw=1,label='2% pressure limit');axes[1].set(ylabel='Relative change (%)',title='100Hz response still needs refinement');axes[1].legend(fontsize=8)
fig.suptitle('Actual native WebGPU calculations — integrated geometry is not response convergence')
fig.savefig(out/'geometry-checks.png',dpi=160);plt.close(fig)
for name in ['comparison.json','studies.json','verification.json','fitted-modal.json','king-investigation.json']:
 if (root/name).exists():shutil.copyfile(root/name,out/name)
(out/'published-curves.json').write_text(json.dumps(current,indent=2),encoding='utf-8')
table=lambda headers,rows:'<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</table>'
curves=[[v['metric'],f"{v['rmse']:.4f}",f"{v['maxError']:.4f}",v['status']] for v in c['comparisons']]
issues='<ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in check['issues'])+'</ul>'
text=f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>ÆGIR0.9.5 numerical audit</title><style>body{{font:16px/1.6 system-ui;color:#173241;background:#f0f4f5;margin:0}}main{{max-width:1100px;margin:auto;padding:40px 24px}}h1,h2{{line-height:1.2}}table{{border-collapse:collapse;background:white;width:100%;font-size:14px}}th,td{{padding:10px;text-align:left;border-bottom:1px solid #dce2e5}}img{{width:100%;height:auto}}.note{{background:#fff5df;padding:18px;border-left:4px solid #b67a19}}</style><main><p>2026-11-04 · ÆGIR0.9.5 · Developer evidence</p><h1>Correct the equations, then check the calculation</h1><p>The source defines cycle =2π rad and Hz=cycle/sec in the <a href="http://quarter-wave.com/Project04/DX3_ML_TL.pdf">DX3 worksheet, p1</a>. Therefore ω/(50Hz) reduces to f/50 for frequency in ordinary Hz. The previous implementation missed this definition and used2πf/50. No density, resistance coefficient, source level or frequency shift was fitted.</p><p>The stuffed opening/driver ratio improves from <strong>{before['openingToDriverRatio']['rmse']:.3f} to {c['openingToDriverRatio']['rmse']:.3f} dB RMS</strong> on the retained <a href="http://quarter-wave.com/TLs/TL_Anatomy.pdf">King2006</a> graph readings. Independent Python/cmath/SciPy and TypeScript calculations agree. Full original2006 code is unavailable; historical-law transfer and sound-speed interpolation remain assumptions.</p><img src="king-correction.png" alt="Corrected stuffed-line ratio and impedance against published readings"><h2>Other stuffed-line curves,10–800Hz</h2>{table(['Metric','RMS error','Maximum error','Compatibility'],curves)}<p>SPL values use assumed drive/distance and are diagnostic. Impedance has no arbitrary SPL gain; source graph uncertainty is ±2Ω and ±2% frequency. Material calibration is still assumed. Published simulation agreement is not physical validation.</p><h2>Conservative3D geometry and automatic quality checks</h2><p>Fractional air volumes and open face areas now enter pressure/flow updates, reciprocal piston coupling and material-aware stability limits. The CAD body stays68.58L on20/16/12mm grids and a shifted12mm grid. Piston area is correct to numerical precision. CPU/GPU pressure/circuit/material recordings agree within2.67×10⁻⁶ relativeL2 in the native test.</p><img src="geometry-checks.png" alt="Corrected volume but remaining pressure and impedance grid sensitivity"><p class="note"><strong>Calculation status: {html.escape(check['status'])}.</strong> The automatic test correctly withholds a pass. Pressure changes4.50% on16→12mm; successive impedance changes increase from0.21% to0.56%. Shift and exterior-padding sensitivities are within the declared limits, and all runs settle. These results do not establish broadband convergence.</p>{issues}<p>Unloaded cut-cell modal checks use a pressure-zero mouth, including18mm of outlet neck. The first eight tube modes agree with the analytical spectrum within0.11% at12mm. Exact CAD body volume and modal-domain volume are separate. Thin walls that divide a pressure cell into disconnected air regions are rejected; no artificial path is added.</p><h2>Retained evidence</h2><p><a href="comparison.json">Five-run comparison</a> · <a href="studies.json">Native settings, phasors and archive hashes</a> · <a href="king-investigation.json">Independent unit/sensitivity investigation</a> · <a href="published-curves.json">All published curves and residuals</a> · <a href="fitted-modal.json">Analytical cavity checks</a> · <a href="verification.json">Native verification</a></p><p>No new physical measurements were made. See the agent record for limitations, source hashes and reproduction commands.</p></main></html>'''
(out/'comparison.html').write_text(text,encoding='utf-8');print(str(out/'comparison.html'))
